import java.util.*;

class Solution {
    public int splitArray(int[] nums, int k) {
        long lo = 0, hi = 0;
        for (int x : nums) { lo = Math.max(lo, x); hi += x; }
        while (lo < hi) {
            long mid = lo + (hi - lo) / 2;
            if (groupsNeeded(nums, mid) <= k) hi = mid; // limit is achievable
            else lo = mid + 1;
        }
        return (int) lo;
    }

    private int groupsNeeded(int[] nums, long limit) {
        int groups = 1;
        long cur = 0;
        for (int x : nums) {
            if (cur + x > limit) { groups++; cur = 0; } // next reader starts here
            cur += x;
        }
        return groups;
    }
}

