class Solution:
    def splitArray(self, nums: List[int], k: int) -> int:
        def groups(lim):
            g, cur = 1, 0
            for x in nums:
                if cur + x > lim: g, cur = g + 1, 0
                cur += x
            return g
        lo, hi = max(nums), sum(nums)
        while lo < hi:
            mid = (lo + hi) // 2
            if groups(mid) <= k: hi = mid
            else: lo = mid + 1
        return lo

