function splitArray(nums, k) {
  // DP check (independent of the greedy)
  const n = nums.length, pre = [0];
  for (const x of nums) pre.push(pre[pre.length - 1] + x);
  let dp = new Array(n + 1).fill(Infinity); dp[0] = 0;
  for (let g = 1; g <= k; g++) {
    const nd = new Array(n + 1).fill(Infinity);
    for (let i = 1; i <= n; i++) {
      let best = Infinity;
      for (let j = i - 1; j >= g - 1; j--) { const s = pre[i] - pre[j]; if (s >= best) break; const v = Math.max(dp[j], s); if (v < best) best = v; }
      nd[i] = best;
    }
    dp = nd;
  }
  return dp[n];
}
